import{_ as a,o,c as e,ag as r}from"./chunks/framework.DoUXNnsN.js";const g=JSON.parse('{"title":"工具与工程","description":"","frontmatter":{"title":"工具与工程","aliases":["工程化","软件工程工具","开发工具链","工程基础"],"tags":["工具与工程"],"status":"ai-draft","sources":["基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"50-工具与工程/工具与工程.md","filePath":"50-工具与工程/工具与工程.md"}'),i={name:"50-工具与工程/工具与工程.md"};function n(l,t,d,c,s,h){return o(),e("div",null,[...t[0]||(t[0]=[r(`<blockquote><p>本篇是&quot;50-工具与工程&quot;目录的总览（hub）。读完你应该能：说清&quot;写代码&quot;之外，一个靠谱的软件项目还需要哪些工具和习惯；按推荐顺序把本目录的词条逐篇读完；检查自己电脑上的开发环境是否就绪。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>&quot;工具与工程&quot;是<strong>把代码从&quot;能跑&quot;变成&quot;可靠、可维护、可协作、可交付&quot;的那一圈东西</strong>：终端、环境、版本控制、调试日志、测试、架构、容器、持续集成等。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>会写一点代码最好（任何语言，如 <a href="/Encyclopedia/20-编程语言/Python/Python">Python</a> 或 <a href="/Encyclopedia/20-编程语言/CSharp/CSharp">CSharp</a>），但不是必须。</li><li>其余的在各篇里从零讲起。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>只会写语法，到了真实项目会遇到这些问题：</p><table tabindex="0"><thead><tr><th>场景</th><th>缺的是什么</th></tr></thead><tbody><tr><td>&quot;在我电脑上能跑，到服务器就不行&quot;</td><td>环境变量、依赖管理、容器</td></tr><tr><td>改坏了回不去，两人改同一份代码互相覆盖</td><td>版本控制（Git）</td></tr><tr><td>线上出问题，却不知道发生了什么</td><td>日志、调试方法</td></tr><tr><td>改一处坏三处，不敢动老代码</td><td>测试、分层架构、重构</td></tr><tr><td>每次发布手工拷文件，容易漏</td><td>CI/CD、Docker</td></tr><tr><td>接口你一言我一语，对接总出错</td><td>REST API 设计、JSON/YAML 约定</td></tr></tbody></table><p>在工厂做 MES/WMS 这类系统时，这些问题的代价更大：一次发布出错可能让产线停线，所以工程习惯不是锦上添花。</p><h2 id="核心概念-一张-工具地图" tabindex="-1">核心概念：一张&quot;工具地图&quot; <a class="header-anchor" href="#核心概念-一张-工具地图" aria-label="Permalink to &quot;核心概念：一张&quot;工具地图&quot;&quot;">​</a></h2><p>软件的一生可以粗略分成：<strong>写 -&gt; 管 -&gt; 验 -&gt; 发 -&gt; 看</strong>。</p><table tabindex="0"><thead><tr><th>阶段</th><th>要做什么</th><th>对应词条</th></tr></thead><tbody><tr><td>写</td><td>终端里操作系统、配环境、写文档和配置</td><td><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a>、<a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>、<a href="/Encyclopedia/50-工具与工程/开发工具">开发工具</a>、<a href="/Encyclopedia/50-工具与工程/Markdown">Markdown</a>、<a href="/Encyclopedia/50-工具与工程/JSON-XML-YAML">JSON-XML-YAML</a></td></tr><tr><td>管</td><td>版本控制、协作、流程</td><td><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 系列、<a href="/Encyclopedia/50-工具与工程/软件开发流程">软件开发流程</a></td></tr><tr><td>验</td><td>排错、测试、规范</td><td><a href="/Encyclopedia/50-工具与工程/调试与排错方法">调试与排错方法</a>、<a href="/Encyclopedia/50-工具与工程/日志">日志</a>、<a href="/Encyclopedia/50-工具与工程/软件测试">软件测试</a>、<a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a></td></tr><tr><td>设</td><td>把系统拆得清楚</td><td><a href="/Encyclopedia/50-工具与工程/软件架构分层">软件架构分层</a>、<a href="/Encyclopedia/50-工具与工程/设计模式">设计模式</a>、<a href="/Encyclopedia/50-工具与工程/REST-API设计">REST-API设计</a></td></tr><tr><td>发</td><td>打包、部署、自动化</td><td><a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a> 系列、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a></td></tr><tr><td>看</td><td>线上运行情况</td><td><a href="/Encyclopedia/50-工具与工程/日志">日志</a></td></tr></tbody></table><h2 id="推荐入门路径" tabindex="-1">推荐入门路径 <a class="header-anchor" href="#推荐入门路径" aria-label="Permalink to &quot;推荐入门路径&quot;">​</a></h2><p>按下面顺序读，前面的是后面的地基。每一步都标了&quot;读完你能做到什么&quot;。</p><ol><li><strong><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a></strong>、<strong><a href="/Encyclopedia/50-工具与工程/PowerShell">PowerShell</a></strong>：能用终端进目录、看文件、运行程序。Windows 上两个都要知道。</li><li><strong><a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a></strong>：搞懂为什么装好了软件却提示&quot;不是内部或外部命令&quot;。</li><li><strong><a href="/Encyclopedia/50-工具与工程/开发工具">开发工具</a></strong>：认识 Visual Studio、VS Code、数据库管理工具等，装好自己的工作台。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a></strong>（总览）-&gt; <strong><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a></strong>：版本控制，每个程序员的必修课，建议尽早学，越早用越省事。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Markdown">Markdown</a></strong>、<strong><a href="/Encyclopedia/50-工具与工程/JSON-XML-YAML">JSON-XML-YAML</a></strong>：写文档和读写配置、接口数据的基本功。</li><li><strong><a href="/Encyclopedia/50-工具与工程/调试与排错方法">调试与排错方法</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/日志">日志</a></strong>：出问题时怎么一步步找到原因。</li><li><strong><a href="/Encyclopedia/50-工具与工程/软件测试">软件测试</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a></strong>：让改代码不再提心吊胆。</li><li><strong><a href="/Encyclopedia/50-工具与工程/软件架构分层">软件架构分层</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/设计模式">设计模式</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/REST-API设计">REST-API设计</a></strong>：从&quot;写函数&quot;升级到&quot;设计系统&quot;。</li><li><strong><a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a></strong> -&gt; <strong><a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a></strong>：把应用和环境一起打包。</li><li><strong><a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a></strong>：把&quot;拉代码、编译、测试、部署&quot;变成自动流水线。</li><li><strong><a href="/Encyclopedia/50-工具与工程/软件开发流程">软件开发流程</a></strong>：把以上都放回团队协作的大图里（需求、开发、测试、发布、维护）。</li></ol><p>如果时间有限，最低配的&quot;必须会&quot;是：<strong>命令行 + 环境变量 + Git（读到远程仓库） + 调试日志</strong>。其余可在项目里遇到再补。</p><h2 id="逐步例子-检查自己的开发环境" tabindex="-1">逐步例子：检查自己的开发环境 <a class="header-anchor" href="#逐步例子-检查自己的开发环境" aria-label="Permalink to &quot;逐步例子：检查自己的开发环境&quot;">​</a></h2><p>下面这组命令能快速告诉你工具链就绪了没有。在 Git Bash 里运行（PowerShell 里同样有效）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git --version</span></span>
<span class="line"><span>git version 2.54.0.windows.1</span></span>
<span class="line"><span>$ python --version</span></span>
<span class="line"><span>Python 3.12.10</span></span>
<span class="line"><span>$ node --version</span></span>
<span class="line"><span>v24.15.0</span></span>
<span class="line"><span>$ dotnet --version</span></span>
<span class="line"><span>10.0.401</span></span></code></pre></div><p>以上是笔者电脑的实际输出，版本号你的会不同，只要不报错、能显示版本即可。如果报&quot;command not found&quot;或&quot;不是内部或外部命令&quot;，就是对应软件没装，或者装了但所在目录没进 PATH（见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>）。</p><p>再看看终端是从哪里找到 <code>git</code> 的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ which git</span></span>
<span class="line"><span>/mingw64/bin/git</span></span></code></pre></div><p><code>which</code>（Git Bash 里）告诉你命令对应的可执行文件位置；PowerShell 里对应 <code>(Get-Command git).Source</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>给自己建一个&quot;工程化小清单&quot;，一次走通&quot;终端 + Git + 文档&quot;：</p><ol><li>打开终端，运行上面四条版本命令，记下哪些没装。</li><li>新建文件夹 <code>toolbox-lab</code>，<code>cd</code> 进去，<code>git init -b main</code>。</li><li>写一个 <code>README.md</code>（Markdown），内容为你的环境版本列表。</li><li><code>git add README.md</code>，<code>git commit -m &quot;docs: add environment checklist&quot;</code>（先按 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 配好 <code>user.name</code>/<code>user.email</code>）。</li><li><code>git log --oneline</code> 应看到 1 条记录。到此你已完成第一个&quot;可追溯的工程化动作&quot;。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>一口气想学完所有工具</strong>：不现实。按&quot;遇到问题再补&quot;的节奏，先把 Git 和命令行练熟。</li><li><strong>只学工具不动手</strong>：每个词条都带实验，亲手运行比读十遍有用。</li><li><strong>环境装了一堆、版本冲突</strong>：记录每个项目需要的版本；后续用 <a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a> 或虚拟环境隔离。</li><li><strong>Windows 与 Linux 命令混用报错</strong>：先确认当前是 Git Bash 还是 PowerShell，两者语法不同。</li></ul><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：工程化直接影响交付：发布是否稳定、出故障能否快速定位和回退、新同事能否很快上手。工厂系统停一小时可能影响整条线，所以版本可追溯、日志完整、测试覆盖关键流程是基本要求。</li><li><strong>技术视角</strong>：本目录的各项工具在一条链上衔接：代码进 Git -&gt; 推送触发 CI 自动构建测试 -&gt; 打包成 Docker 镜像 -&gt; 部署；运行时靠日志观测、靠配置（环境变量、YAML/JSON）适配环境。后续在 <a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a> 与 <a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server">SQL-Server</a> 的章节里会反复用到这些。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> &quot;在我电脑上能跑，服务器不行&quot;，最可能和本目录哪几项有关？ 答：环境变量与 PATH（配置不同）、依赖版本不一致、没有用 Docker 等方式统一环境。</p><p><strong>2.</strong> 为什么建议最早学 Git？ 答：几乎所有后续实践（协作、CI/CD、代码评审）都建立在 Git 之上，而且它还是个人最好的&quot;后悔药&quot;。</p><p><strong>3.</strong> 下面哪项属于&quot;验&quot;：日志、Docker、测试、设计模式？ 答：测试（日志偏运行观测与排错，Docker 偏发布，设计模式偏设计）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具与工程 = 写 -&gt; 管 -&gt; 验 -&gt; 发 -&gt; 看 的整套习惯。</li><li>最低配：命令行、环境变量、Git、调试日志。</li><li>按推荐路径读，每篇带实验；遇到问题再回头补。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker">Docker</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>、<a href="/Encyclopedia/50-工具与工程/软件测试">软件测试</a>、<a href="/Encyclopedia/10-计算机基础/计算机基础">计算机基础</a>、<a href="/Encyclopedia/20-编程语言/编程语言">编程语言</a>、<a href="/Encyclopedia/30-.NET生态/dotNET">dotNET</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git（免费在线书）：<a href="https://git-scm.com/book/zh/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2</a></li><li>Missing Semester of Your CS Education（MIT 公开课，讲命令行、Git、调试等工具）：<a href="https://missing.csail.mit.edu/" target="_blank" rel="noreferrer">https://missing.csail.mit.edu/</a></li></ul>`,40)])])}const u=a(i,[["render",n]]);export{g as __pageData,u as default};
